/**
 * n8n Code node — wf6 step 0: build today's persona posting slots.
 *
 * Output: one item per persona slot, with scheduled_at, length_band, tone, format.
 *
 * Rules:
 *  - Slots are placed at persona_slot_hours (defaults [7, 11, 16, 21] Kuala Lumpur time).
 *  - Each slot is jittered ±persona_jitter_min (default 22 min) for irregularity.
 *  - persona_skip_prob (default 8%) chance a slot is dropped — irregularity.
 *  - Length-band mix is configurable: micro/mid/long (default 25/60/15).
 *  - Tone is drawn from a persona-appropriate subset (no enthusiast, no corporate_parody —
 *    those read like influencers or parody accounts).
 *  - Format is drawn from persona-appropriate formats (confession, one_liner, chat_narration,
 *    overheard, list_of_three, question_hook) — no honest_review/diary/myth_bast/product frames.
 *  - Media type is always TEXT for persona posts (no product photos to attach).
 */

const ALLOWED_TONES = ['deadpan', 'gaul', 'warm_sibling', 'chaotic', 'minimal'];
const ALLOWED_FORMATS = ['confession', 'one_liner', 'chat_narration', 'overheard',
                         'list_of_three', 'question_hook', 'pov'];

const DEFAULT_SETTINGS = {
  persona_slot_hours: [7, 11, 16, 21],
  persona_jitter_min: 22,
  persona_skip_prob: 0.08,
  persona_micro_pct: 0.25,
  persona_mid_pct: 0.60,
  persona_long_pct: 0.15,
  timezone: 'Asia/Kuala_Lumpur',
};

function pickWeighted(rng, pairs) {
  const total = pairs.reduce((s, p) => s + p.w, 0);
  let r = rng() * total;
  for (const p of pairs) { r -= p.w; if (r <= 0) return p.v; }
  return pairs[pairs.length - 1].v;
}

function buildPersonaSlots(opts = {}) {
  const settings = { ...DEFAULT_SETTINGS, ...(opts.settings ?? {}) };
  const now = new Date();
  const tz = settings.timezone ?? 'Asia/Kuala_Lumpur';

  // We run at 03:30 (after wf2's 03:00 product generation finishes), so slots are for TODAY or
  // TOMORROW depending on hour. For simplicity: if before 05:00 local, generate for today;
  // otherwise for tomorrow.
  const d = new Date(now);
  // Compute local hour in timezone.
  const localHourStr = new Intl.DateTimeFormat('en-US', {
    hour: '2-digit', hour12: false, timeZone: tz,
  }).format(d);
  const localHour = Number(localHourStr) % 24;
  if (localHour >= 5) d.setDate(d.getDate() + 1);
  // Set to midnight local time in the timezone.
  const parts = new Intl.DateTimeFormat('en-CA', {
    year: 'numeric', month: '2-digit', day: '2-digit', timeZone: tz,
  }).formatToParts(d);
  const y = Number(parts.find(p => p.type === 'year').value);
  const m = Number(parts.find(p => p.type === 'month').value) - 1;
  const day = Number(parts.find(p => p.type === 'day').value);
  const dayStart = new Date(Date.UTC(y, m, day, 0, 0, 0));
  // UTC offset for the timezone at that date — this gives us the right UTC start.
  const tzOffsetMs = (() => {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
    const parts2 = dtf.formatToParts(new Date(Date.UTC(y, m, day, 12, 0, 0)));
    const obj = {};
    for (const p of parts2) obj[p.type] = Number(p.value);
    const asUtc = Date.UTC(obj.year, obj.month - 1, obj.day, obj.hour % 24, obj.minute, obj.second);
    return asUtc - Date.UTC(obj.year, obj.month - 1, obj.day, 12, 0, 0);
  })();
  const localMidnight = new Date(dayStart.getTime() - tzOffsetMs);

  const slots = [];
  const hours = settings.persona_slot_hours;
  for (let i = 0; i < hours.length; i++) {
    if (Math.random() < (settings.persona_skip_prob ?? 0.08)) continue;

    const jitter = Math.round((Math.random() * 2 - 1) * (settings.persona_jitter_min ?? 22));
    const t = new Date(localMidnight);
    t.setHours(hours[i], 0, 0, 0);
    t.setMinutes(t.getMinutes() + jitter);
    t.setSeconds(Math.floor(Math.random() * 60));

    const r = Math.random();
    let length_band = 'mid';
    if (r < settings.persona_micro_pct) length_band = 'micro';
    else if (r < settings.persona_micro_pct + settings.persona_mid_pct) length_band = 'mid';
    else length_band = 'long';

    // Tone: simple uniform draw from allowed set. Bandit scoring will update post-hoc via
    // wf4 extension — we extend topic bandit first; tone selection stays uniform for personas
    // until we have enough samples per tone on persona posts to learn.
    const tone = ALLOWED_TONES[Math.floor(Math.random() * ALLOWED_TONES.length)];
    const format = ALLOWED_FORMATS[Math.floor(Math.random() * ALLOWED_FORMATS.length)];

    slots.push({
      slot_index: i,
      scheduled_at: t.toISOString(),
      length_band,
      tone,
      format,
      angle: 'utility',           // personas aren't selling; 'utility' is "one small useful/true thing"
      sell_intensity: '0',        // never any CTA
      media_type: 'TEXT',
      is_carousel: false,
      reply_delay_sec: 0,
      purpose: 'persona',
      timezone: tz,
    });
  }

  // Never produce zero persona slots (guards against 8% skip rolling all 4 slots).
  if (slots.length === 0) {
    const t = new Date(localMidnight);
    t.setHours(20, 12, Math.floor(Math.random() * 60), 0);
    slots.push({
      slot_index: 0, scheduled_at: t.toISOString(),
      length_band: 'mid', tone: 'gaul', format: 'one_liner',
      angle: 'utility', sell_intensity: '0', media_type: 'TEXT',
      is_carousel: false, reply_delay_sec: 0, purpose: 'persona', timezone: tz,
    });
  }
  return slots;
}

// n8n entry point: receives $json with `settings` (or falls back to defaults).
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const slots = buildPersonaSlots({ settings: $json.warmup ?? $json.settings ?? {} });
  return slots.map(s => ({ json: { ...$json, ...s } }));
}

if (typeof module !== 'undefined') {
  module.exports = { buildPersonaSlots, ALLOWED_TONES, ALLOWED_FORMATS };
}

/**
 * n8n Code node — wf6 step 1: pick one persona topic via Thompson sampling.
 *
 * Mirrors bandit.js's SELECT logic, but over persona_topics rather than products/arms.
 *
 * Input $json (set by the preceding Postgres "load persona_topics" node):
 *   topics    : [{id, uid, topic, angle_hint, niche_tags, alpha, beta, n, cooldown_until, context, pinned}]
 *   last_n_ids: array of topic ids used in the last 7 days (avoid repetition)
 *   settings  : { bandit: { epsilon, cooldown_days, ... } }
 *   scheduled_at, timezone
 *
 * Output:
 *   Adds `{ topic: <chosen row>, purpose: 'persona' }` to the current item.
 */

// Gamma(k,1) via Marsaglia-Tsang (copy of bandit.js helper — kept standalone so this
// node can be pasted into n8n without requiring require()/import).
function gammaSample(k) {
  if (k < 1) return gammaSample(k + 1) * Math.pow(Math.random(), 1 / k);
  const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x, v;
    do { x = normalSample(); v = 1 + c * x; } while (v <= 0);
    v = v * v * v;
    const u = Math.random();
    if (u < 1 - 0.0331 * x * x * x * x) return d * v;
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
}
function normalSample() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function betaSample(a, b) {
  const x = gammaSample(Math.max(a, 0.05)), y = gammaSample(Math.max(b, 0.05));
  return x / (x + y);
}

function pickTopic({ topics, lastNIds = [], settings = {} }) {
  topics = Array.isArray(topics) ? topics : [];
  if (!topics.length) throw new Error('persona_topic_pick: no topics supplied');
  const now = Date.now();

  // Filter out topics in cooldown and topics used very recently (within last 7 days),
  // unless pinning forces one through.
  const recentlyUsed = new Set(lastNIds ?? []);
  const live = topics.filter(t => {
    if (t.pinned) return true;
    if (t.cooldown_until && new Date(t.cooldown_until).getTime() > now) return false;
    if (recentlyUsed.has(t.id)) return false;
    return true;
  });

  // Prefer the filtered pool whenever it has anything — never serve a cooled-down topic
  // unless literally nothing else exists.
  const pool = live.length >= 1 ? live : topics;

  const eps = settings?.bandit?.epsilon ?? 0.2;

  // Pinned topics get priority 70% of the time when present (operator override).
  const pinned = pool.filter(t => t.pinned);
  if (pinned.length && Math.random() < 0.7) {
    return pinned[Math.floor(Math.random() * pinned.length)];
  }

  if (Math.random() < eps) {
    // EXPLORE: uniform random, biased toward least-sampled (alpha close to 1 = not yet sampled).
    const shuffled = [...pool].sort((a, b) =>
      (Number(a.alpha ?? 1) + Math.random() * 2) - (Number(b.alpha ?? 1) + Math.random() * 2));
    return shuffled[0];
  }

  // EXPLOIT: Thompson-sample Beta(alpha,beta).
  let best = null, bestDraw = -1;
  for (const t of pool) {
    const a = Number(t.alpha ?? 1);
    const b = Number(t.beta ?? 1);
    // Cold-start boost for fresh topics so they get sampled at least once before the bandit
    // trusts the 0/0 prior — an (alpha=1,beta=1) draw can still land anywhere in [0,1], but
    // topics with n===0 get a tiny extra exploration push.
    const draw = Number(t.n ?? 0) === 0 ? Math.max(betaSample(a, b), 0.3 + Math.random() * 0.4)
                                        : betaSample(a, b);
    if (draw > bestDraw) { bestDraw = draw; best = t; }
  }
  return best ?? pool[0];
}

// n8n entry point. n8n's Code node provides $json for the current item.
if (typeof $ !== 'undefined' && typeof $json !== 'undefined') {
  const picked = pickTopic($json);
  return [{ json: { ...$json, topic: picked, purpose: 'persona' } }];
}

if (typeof module !== 'undefined') {
  module.exports = { pickTopic };
}

/**
 * n8n Code node — wf2 persona calibration.
 *
 * Input:
 *   $json.cfg.persona_snippets : [{id, domain, title, register, tags, text}]
 *   $json.tone                 : selected tone code from bandit
 *   $json.product              : product object with category_hint / enrichment
 *
 * Output:
 *   Adds persona_snippets + persona_fragment for the writer prompt.
 *
 * The snippets are style/rhythm references only. They must never become facts in a product post.
 */

function shuffle(xs) {
  const a = [...xs];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function toneRegisters(tone) {
  return ({
    warm_sibling: ['reflective', 'conversational'],
    deadpan: ['neutral', 'informative'],
    minimal: ['neutral', 'informative'],
    gaul: ['conversational', 'neutral'],
    chaotic: ['conversational'],
    enthusiast: ['conversational', 'informative'],
    corporate_parody: ['formal', 'informative'],
  })[tone] ?? ['conversational', 'neutral', 'reflective'];
}

function clean(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

function categoryScore(snippet, product) {
  if (!product) return 0;
  const categoryText = String(
    product.category_hint || product.enrichment?.category || product.name || ''
  ).toLowerCase();

  const domain = String(snippet.domain || snippet.source_domain || '').toLowerCase();
  const text = String(snippet.text || '').toLowerCase();

  const techKeywords = ['tech', 'gadget', 'phone', 'laptop', 'wireless', 'usb', 'charger', 'audio', 'sound', 'camera', 'peranti', 'skrin', 'bateri', 'moniter', 'keyboard'];
  const lifestyleKeywords = ['rumah', 'dapur', 'baju', 'kasut', 'skin', 'beauty', 'mask', 'kain', 'makanan', 'decor', 'bilik', 'budak', 'anak', 'beg'];

  const isTechProduct = techKeywords.some(k => categoryText.includes(k));
  const isLifestyleProduct = lifestyleKeywords.some(k => categoryText.includes(k));

  if (isTechProduct && (domain.includes('amanz') || text.includes('peranti') || text.includes('spesifikasi'))) {
    return 3;
  }
  if (isLifestyleProduct && (domain.includes('iium') || domain.includes('facebook') || snippet.register === 'reflective')) {
    return 3;
  }
  return 0;
}

function pickPersonaSnippets(input) {
  const all = input.persona_snippets ?? input.cfg?.persona_snippets ?? [];
  if (!Array.isArray(all) || !all.length) return { persona_snippets: [], persona_fragment: '' };

  const preferred = toneRegisters(input.tone);
  const product = input.product || input.product_data || {};

  const ranked = all
    .map(s => {
      const cleanedText = clean(s.text);
      let score = preferred.includes(s.register) ? 2 : 0;
      score += categoryScore(s, product);
      return { ...s, text: cleanedText, score };
    })
    .filter(s => s.text.length >= 80 && s.text.length <= 750)
    .sort((a, b) => b.score - a.score || Math.random() - 0.5);

  const picked = shuffle(ranked.slice(0, 12)).slice(0, 3);
  if (!picked.length) return { persona_snippets: [], persona_fragment: '' };

  const lines = picked.map((s, i) => {
    const label = [s.register, s.domain || s.source_domain].filter(Boolean).join(' · ');
    return `${i + 1}. (${label}) ${s.text.slice(0, 520)}`;
  });

  return {
    persona_snippets: picked,
    persona_fragment: `\n### Persona calibration — Malaysian cadence references\nThese are NOT facts and NOT templates. Borrow only rhythm, sentence pressure, and Malay register. Do not copy wording, claims, religious advice, or topic.\n${lines.join('\n')}\n`,
  };
}

if (typeof $json !== 'undefined') {
  const picked = pickPersonaSnippets($json);
  return [{ json: { ...$json, ...picked } }];
}

if (typeof module !== 'undefined') {
  module.exports = { pickPersonaSnippets, toneRegisters, categoryScore };
}

// Build writer + editor prompt strings from the loaded topic/lever.
// Output sets writer_system, writer_user, editor_system, editor_user, post_uid for the INSERT.
const d = $json;
const topic = d.topic || {};
const snippets = d.persona_snippets || d.cfg?.persona_snippets || [];
const recent = d.recent || d.cfg?.recent || [];
const llm = d.cfg?.llm || d.llm || {};

// Pick 0-3 random persona snippets (none ~25% of the time, for voice variety).
let persona_fragment = '';
if (snippets.length && Math.random() > 0.25) {
  const shuffled = [...snippets].sort(() => Math.random() - 0.5).slice(0, 2);
  persona_fragment =
    '### Persona calibration — real Malaysian cadence references\n' +
    'Borrow RHYTHM, SENTENCE PRESSURE, and REGISTER only. Do not copy wording, facts, or topic.\n' +
    shuffled.map((s,i)=>'('+(s.register||'neutral')+' · '+(s.domain||'')+') '+String(s.text||'').slice(0,420)).join('\n');
}

// Format lever labels so prompts have human-readable names — the bandit sets codes.
const LEVER_LABELS = {
  format: {
    flash_story:['Cerita kilat','Mikro-cerita 3 babak'],
    confession:['Pengakuan','Nada pengakuan peribadi'],
    pov:['POV','Satu saat dari sudut orang kedua'],
    chat_narration:['Cerita balik perbualan','Petikan perbualan pendek'],
    list_of_three:['Tiga pemerhatian','Tiga perkara kecil, baris berasingan'],
    one_liner:['Satu baris','Maksimum dua ayat pendek'],
    honest_review:['Pemerhatian jujur','Satu kelemahan / kelebihan yang spesifik'],
    diary:['Diari','Catatan hari dengan butiran deria kecil'],
    myth_bust:['Pecahkan tanggapan','Patahkan andaian umum dengan pengalaman sendiri'],
    overheard:['Terdengar','Cerita sesuatu yang kedengaran di tempat awam'],
    before_after:['Sebelum-selepas','Dua perenggan berlawanan tanpa kata "sebelum"/"selepas"'],
    question_hook:['Soalan umpan','Soalan sangat spesifik, jawab separuh'],
  },
  tone: {
    deadpan:['Datar','Tiada emoji, tiada seru, humor kering'],
    gaul:['Santai','Bahasa Melayu pasar harian: tak, nak, dah, je, kot, lah'],
    warm_sibling:['Macam abang/kakak','Mesra, menenangkan, jangan berlagak pandai'],
    corporate_parody:['Parodi korporat','Bahasa pejabat secara melampau untuk lawak'],
    chaotic:['Bersepah','Ayat terputus-putus, satu idea utama'],
    minimal:['Minimalis','Ayat pendek, ruang kosong, tiada emoji'],
    enthusiast:['Teruja','Teruja tapi ada sebab konkrit'],
  },
  length_band: {
    micro:['Mikro','Maksimum 120 aksara'],
    mid:['Sederhana','120–260 aksara'],
    long:['Panjang','260–480 aksara, 2-3 perenggan pendek'],
  },
};
const get = (kind, code) => {
  const m = LEVER_LABELS[kind]?.[code] || [code, ''];
  return { label: m[0], brief: m[1] };
};
const lever = {
  tone_label: get('tone', d.tone).label,
  tone_brief: get('tone', d.tone).brief,
  format_label: get('format', d.format).label,
  format_brief: get('format', d.format).brief,
  length_band_label: get('length_band', d.length_band).label,
  length_band_brief: get('length_band', d.length_band).brief,
};

// Writer prompt (mirrors prompts/persona_writer.md, filled for this slot).
const writer_system = "You are a regular Malaysian person on Threads, posting from your phone between life things.\nYou are NOT a brand, NOT an influencer, NOT a reviewer, NOT trying to sell anything.\n\nThese posts exist because your account needs to feel alive. Someone scrolling your profile\nshould think \"this is a normal person\" — not \"this is an account that posts product links.\"\n\nHard rules:\n1. Write in casual **Malaysian Malay** (Bahasa Melayu harian), NOT Indonesian and NOT formal\n   Dewan Bahasa. Use: tak, nak, dah, je, kot, lah, kan, memang, boleh, tengok, letak, guna.\n   Rojak with common English words is normal — don't avoid it. Short typos (td, yg, sbb) allowed\n   at most once per post if natural.\n\n   **Never use Indonesian words:** banget, nggak, gak, aja, udah, bikin, gimana, kalian,\n   doang, cowok, cewek, gue, deh, dong, sih.\n\n   **False friends that must never appear:**\n   - `bisa` means venom in Malay — use `boleh`\n   - `butuh` is vulgar in Malay — use `perlu`\n   - `pusing` means \"to turn\" in Malay, not dizzy — use `pening` or `sakit kepala`\n\n   Currency is RM (ringgit). Never Rp or rupiah.\n\n2. **No links. No mentions of Shopee, Lazada, TikTok Shop, affiliate, voucher, discount,\n   promo, checkout, order, klik, \"link kat bawah\", bio, DM, WA.me.** This is a hard rule.\n3. **No selling.** Never \"korang kena try\", never \"wajib ada\", never \"best gila\", never\n   \"game-changer\". You are allowed to have opinions, but opinions read like opinions, not ads.\n4. No rhetorical crowd-openers:\n   - \"Korang pernah tak...\"\n   - \"Siapa kat sini yang...\"\n   - \"Ada tak yang...\"\n   - \"Jom...\"\n   - \"Hai korang / Assalammualaikum semua\"\n   - \"Thread kali ini...\"\n5. No emoji rows. Max 2 emoji. For tone=deadpan/minimal: 0 emoji.\n6. No hashtags unless explicitly told to add one (max 1, ≤40% chance).\n7. Output ONLY the post text. No preamble, no quotes, no \"Berikut adalah...\" / \"Here is...\",\n   no explanation, no options.\n8. You must land at least one small, specific detail (a time of day, a place, a sound, a\n   price, the way something smelled, a specific body sensation, a kerenah). Generic posts\n   are the fastest way to look like an AI. This rule is what separates you from every\n   generic \"relatable\" account on Threads.\n9. Length follows the {{length_band}} band. No thread markers (1/5, 🧵). You are posting ONE post.\n\nYou are writing ONE post. Not variations. Not a list.";

let angleHint = topic.angle_hint
  ? 'Suggested angle: ' + topic.angle_hint + ' (do not name the angle in the post).'
  : '';
let timelyNote = topic.context?.timely_note
  ? ('Timely context (flavour only; never state "menurut" / cite a source / treat as fact):\n' + topic.context.timely_note)
  : '';
let anglesList = Array.isArray(topic.context?.angles) && topic.context.angles.length
  ? ('Possible angles (pick ONE, do not list):\n' + topic.context.angles.map(a=>'- '+a).join('\n'))
  : '';

const openerList = (recent && recent.length)
  ? recent.slice(0,20).map(r=>'- '+String(r.body||'').split(/\s+/).slice(0,5).join(' ')).join('\n')
  : '(none yet)';

const writer_user =
  '### Topic for today\n' +
  '**' + (topic.topic||'') + '**\n' +
  angleHint + (angleHint?'\n':'') +
  timelyNote + (timelyNote?'\n\n':'') +
  anglesList + (anglesList?'\n\n':'') +
  '\n### Assignment\n' +
  '- Tone: **' + lever.tone_label + '** — ' + lever.tone_brief + '\n' +
  '- Format: **' + lever.format_label + '** — ' + lever.format_brief + '\n' +
  '- Length: **' + lever.length_band_label + '** — ' + lever.length_band_brief + '\n' +
  '- Media: **TEXT only** (no image). The words must carry everything.\n' +
  '\n### Openings already used recently — do NOT repeat any of these\n' +
  openerList + '\n\n' +
  persona_fragment + '\n\n' +
  '### One more thing\n' +
  'Ground this in a single tiny moment. One time. One place. One sensation.\n' +
  'Write the post now.';

const editor_system = "You are an editor for a Malaysian person's personal Threads account. You receive a drafted persona post (NO links, NO selling). Your job:\n1. Keep the same meaning, voice, rhythm, and first-person point of view.\n2. Trim any phrase that sounds like marketing, a template, or an AI (\"inilah\", \"marilah\", \"wajib tau\", \"korang mesti\").\n3. Fix any Indonesian slip-ups (banget/nggak/gak/bisa/butuh/aja/udah) to Malay (sangat/tak/boleh/perlu/saja/sudah).\n4. Keep it under 500 chars and in one paragraph unless the original uses line breaks intentionally.\n5. Output ONLY the cleaned post. No quotes, no preamble, no explanation.";
const editor_user_prefix = 'Here is a drafted Threads persona post. Clean it up so a real Malaysian person would have typed it. Keep the same opening idea.\n\nDraft:\n';

// Stable short uid for the post (used as redirect slug placeholder; persona posts have no CTA but we still need a uid).
function shortUid() {
  const chars = 'abcdefghjkmnpqrstuvwxyz23456789';
  let s = '';
  for (let i=0;i<6;i++) s += chars[Math.floor(Math.random()*chars.length)];
  return 'p' + s;
}

return [{ json: {
  ...d,
  writer_system, writer_user,
  editor_system, editor_user_prefix,
  topic,
  post_uid: 'p' + shortUid().slice(1),
} }];

/**
 * n8n Code node — wf6 QA gate for persona posts.
 *
 * Reuses qa.js's structural checks (length, emoji, caps, repetition, similarity, opener uniqueness)
 * and tightens the rules for pure-engagement posts:
 *   - NO affiliate/promo words (Shopee, Lazada, link, klik, beli, etc)
 *   - NO broadcasters' openers ("Korang pernah tak...", "Siapa kat sini...")
 *   - NO product names or prices (there is no product on a persona post)
 *   - MUST contain at least one specific/concrete anchor (time, place, RM amount, body sensation,
 *     kedai, mamak, dapur, etc) — generic "relatable" platitudes are rejected
 *   - Questions are allowed, but question-sandwich (open with ? AND close with ?) is still banned
 *   - Same 500-char hard cap, same Indonesian word bans, same shouting cap
 *
 * Input $json:
 *   text            : candidate body from the editor/rewrite LLM pass
 *   embedding       : number[] embedding of the candidate
 *   recent          : [{body, embedding}] last 30 posts (purpose-agnostic)
 *   banned          : [{pattern, scope}] from banned_phrases (persona_opener / persona_all are included)
 *   length_band     : 'micro'|'mid'|'long'
 *   tone            : lever code
 *   settings        : qa settings
 */

const EMOJI_RE = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu;

// Promo/sell words persona posts MUST never contain.
const PERSONA_SELL_WORDS = /\b(shopee|lazada|tiktok.?shop|affiliate|voucher|diskaun|discount|promo|checkout|order|co\b|beli sekarang|klik link|link di (bawah|bio|komen)|DM saya|wa\.me|t\.me|bio saya|link ada)\b/i;

// Words/phrases that a "real person" doesn't open with. Caught by banned_phrases with scope
// 'persona_opener', but duplicated here as a defense in case the DB rows are missing.
const PERSONA_BAD_OPENERS = [
  /^\s*Korang (pernah|rasa|tahu|perasan) tak\b/i,
  /^\s*Siapa (kat sini|di sini|yang)\b/i,
  /^\s*(Jom|Jangan lepaskan|Save dulu|Share|Hai semua|Assalammualaikum semua|Hi korang)\b/i,
  /^\s*(Thread|Post) kali ini\b/i,
  /^\s*(Saya nak share|Nak share|Harini saya nak share)\b/i,
];

// Concrete anchors — at least one of these categories must be present. This is the
// specificity enforcement that stops the output from reading as generic "relatable content".
const ANCHOR_PATTERNS = [
  /\bRM\s?\d+/,                                    // money (RM4, RM 3.50)
  /\b\d+\s?(minit|jam|hari|minggu|bulan|tahun)\b/i,// time
  /\b(pagi|tengahari|petang|malam|subuh|maghrib)\b/i,
  /\b(mamak|kopitiam|warung|kedai|dapur|bilik|pejabat|ofis|lif|escalator|lrt|mrt|komuter|highway|traffic light)\b/i,
  /\b(hujan|panas|petir|ribut|jerebu)\b/i,
  /\b(nasi|kicap|sambal|teh tarik|teh o|kopi o|milo|roti canai|roti|sup|maggi|kari|sayur)\b/i,
  /\b(wangi|bau|panas|sejuk|lembap|licin|kasar|melekit|berdecit|berdentum)\b/i,  // sensory
  /\b(telefon|phone|laptop|kipas|aircond|rice cooker|peti ais|sinki|cerek|plug|cas)\b/i,  // objects
  /\b(mak|abah|abang|kakak|adik|pakcik|makcik|kawan|boss|rider|cashier)\b/i,      // people
  /\b(semalam|kelmarin|tadi|tadi pagi|petang tadi|pagi tadi|hari tu|masa tu)\b/i, // time deictics
  /\d/,                                             // any digit (minutes, degrees, ringgit, quantity)
];

// Indonesian false friends — same ban list as qa.js, repeated so this module is standalone.
const INDONESIAN_BAN = /\b(banget|nggak|gak|aja|udah|bikin|gimana|kalian|doang|cowok|cewek|gue|deh|dong|sih)\b/i;
const FALSE_FRIENDS = [
  [/\bbisa\b/i, 'bisa = venom in BM; use boleh'],
  [/\bbutuh\b/i, 'butuh = vulgar in BM; use perlu'],
  [/\bpusing\b(?!\s+(kiri|kanan|sana))/i, 'pusing = turn in BM; use pening/sakit kepala'],
];

function cosine(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}

function shingleOverlap(a, b, n = 3) {
  const grams = t => {
    const w = t.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
    const s = new Set();
    for (let i = 0; i + n <= w.length; i++) s.add(w.slice(i, i + n).join(' '));
    return s;
  };
  const A = grams(a), B = grams(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const g of A) if (B.has(g)) inter++;
  return inter / (A.size + B.size - inter);
}

function qaPersona(input) {
  const cfg = input.settings?.qa ?? input.settings ?? {};
  const reasons = [];
  let text = String(input.text ?? '').trim();

  // Strip wrappers the model sometimes adds.
  text = text.replace(/^```[\w]*\n?|```$/g, '').trim();
  text = text.replace(/^["'"](.*)["'"]$/s, '$1').trim();
  text = text.replace(/^(Berikut|Here'?s|Copy:|Post:)\s*:?\s*/i, '').trim();

  // 1. Hard length — 500 Threads cap, with band constraints.
  if (text.length > 500) reasons.push('over Threads 500 char limit');
  const bands = { micro: [1, 120], mid: [90, 270], long: [220, 480] };
  const [lo, hi] = bands[input.length_band] ?? [1, 480];
  if (text.length < lo || text.length > hi) {
    reasons.push(`length ${text.length} outside persona band ${input.length_band} (${lo}-${hi})`);
  }

  // 2. Global banned phrases (scope 'all') + persona-specific (scope 'persona_opener'/'persona_all').
  for (const b of input.banned ?? []) {
    if (!['all', 'persona_opener', 'persona_all'].includes(b.scope)
        && b.scope !== input.tone) continue;
    const target = b.scope === 'persona_opener' || b.scope === 'opener' ? text.slice(0, 70) : text;
    let re;
    try { re = new RegExp(b.pattern, 'iu'); } catch { continue; }
    if (re.test(target)) reasons.push(`banned phrase: ${b.pattern}`);
  }

  // 3. Persona-specific promo/sell word ban (defense in depth even if DB rows are missing).
  if (PERSONA_SELL_WORDS.test(text)) reasons.push('persona post contains promo/sell language');

  // 4. Persona-specific broadcast openers.
  for (const rx of PERSONA_BAD_OPENERS) {
    if (rx.test(text)) { reasons.push('persona post opens with a broadcast/influencer line'); break; }
  }

  // 5. Indonesian + false friends.
  if (INDONESIAN_BAN.test(text)) reasons.push('contains Indonesian word(s)');
  for (const [rx, why] of FALSE_FRIENDS) {
    if (rx.test(text)) { reasons.push(`false friend: ${why}`); break; }
  }

  // 6. Emoji cap (stricter for deadpan/minimal on persona too).
  const emojis = text.match(EMOJI_RE) ?? [];
  const emojiCap = ['deadpan', 'minimal'].includes(input.tone) ? 0 : (cfg.max_emoji ?? 2);
  if (emojis.length > emojiCap) reasons.push(`${emojis.length} emoji > cap ${emojiCap} for tone ${input.tone}`);

  // 7. Hashtag cap (1 max, <40% chance to keep).
  const tags = text.match(/#\w+/g) ?? [];
  if (tags.length > 1) reasons.push('more than 1 hashtag');
  if (tags.length === 1 && Math.random() > (cfg.hashtag_probability ?? 0.3)) {
    text = text.replace(/\s*#\w+/g, '').trim();
  }

  // 8. SHOUTING cap (same threshold as product QA).
  const shout = (text.match(/\b[A-Z]{4,}\b/g) ?? [])
    .filter(w => !/^(RM|OK|USB|LED|PDF|XL|XXL|COD|DIY|FYI|PM|AM|PM|KL|JB|PJ|IOI)$/.test(w));
  if (shout.length >= 3) reasons.push(`${shout.length} ALL-CAPS words — reads as an ad`);
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length >= 8 && shout.length / words.length > 0.25) {
    reasons.push('more than a quarter of the post is shouting');
  }

  // 9. Structural AI tells.
  if ((text.match(/—/g) ?? []).length >= 2) reasons.push('em-dash chain');
  if (/^\s*[-*•]\s/m.test(text)) reasons.push('bullet list in a short persona post');
  if (/\?\s*$/.test(text) && /^\s*\w+.*\?/.test(text.split('\n')[0])) {
    reasons.push('question sandwich');
  }
  if (/(\b\w+\b)(\s+\1\b){2,}/i.test(text)) reasons.push('word repetition');

  // 10. Concrete anchor — at least one ANCHOR_PATTERN must match.
  const hasAnchor = ANCHOR_PATTERNS.some(rx => rx.test(text));
  if (!hasAnchor) reasons.push('persona post has no concrete anchor (time/place/sensation/object/person/number) — too generic');

  // 11. Must NOT reference an image that does not exist (persona posts are text-only).
  if (/\b(gambar|foto|fotonya|gambarnya|di atas|liat nih|lihat gambar|swipe|geser)\b/i.test(text)) {
    reasons.push('text-only persona post references an image');
  }

  // 12. Anti-repetition vs last 30 posts (cosine sim + 3-gram shingle overlap).
  let maxSim = 0, maxShingle = 0;
  for (const r of input.recent ?? []) {
    maxSim = Math.max(maxSim, cosine(input.embedding, r.embedding));
    maxShingle = Math.max(maxShingle, shingleOverlap(text, r.body));
  }
  if (maxSim > (cfg.max_similarity ?? 0.86)) reasons.push(`too similar to a recent post (cos ${maxSim.toFixed(3)})`);
  if (maxShingle > 0.18) reasons.push(`reuses phrasing skeleton (3-gram overlap ${maxShingle.toFixed(3)})`);

  // 13. Opener uniqueness vs last 30 posts (same 5-word rule).
  const opener = t => t.toLowerCase().split(/\s+/).slice(0, 5).join(' ');
  if ((input.recent ?? []).some(r => opener(r.body) === opener(text))) reasons.push('duplicate opener');

  return {
    pass: reasons.length === 0,
    reasons,
    cleaned: text,
    stats: {
      media_type: 'TEXT',
      chars: text.length,
      emoji: emojis.length,
      hashtag: (text.match(/#\w+/g) ?? []).length > 0,
      max_similarity: maxSim,
      max_shingle: maxShingle,
      purpose: 'persona',
    },
  };
}

// n8n entry point — called after the embedding HTTP response, mirroring qa.js's n8nInput().
function n8nInput() {
  if (typeof $ !== 'function') return $json;
  try {
    // Pull base from 'Build prompts' — that's the last Code node before the LLM chain, so it
    // carries slot fields (format, tone, length_band, scheduled_at), cfg, topic, post_uid, etc.
    const base = $('Build prompts').item.json;
    const edited = $('Persona LLM: editor pass').item.json.choices?.[0]?.message?.content ?? '';
    const embedding = $json.data?.[0]?.embedding ?? $json.embedding;
    return {
      ...base,
      text: edited,
      embedding,
      recent: base.cfg?.recent ?? base.recent ?? [],
      banned: base.cfg?.banned ?? base.banned ?? [],
      settings: base.cfg?.qa ?? base.settings?.qa ?? base.qa ?? {},
      tone: base.tone,
      length_band: base.length_band,
    };
  } catch {
    return $json;
  }
}

const input = (typeof $ !== 'undefined' && typeof $json !== 'undefined') ? n8nInput() : null;
if (input) {
  const out = qaPersona(input);
  return [{ json: { ...input, ...out } }];
}

if (typeof module !== 'undefined') {
  module.exports = { qaPersona };
}
